def llm_judge({{judge_call}}, {{question}}, {{answer}}, {{reference}}):
    p = f"Question: {{{question}}}\nReference: {{{reference}}}\nAnswer: {{{answer}}}\nScore 1-5 the answer's correctness. Reply with just the number."
    out = {{judge_call}}(p).strip()
    try: return int(out[0])
    except: return 0
